action.code:
uint32_t crc = init_crc;
data += n;
while (n >= 8) {
    crc ^= 0x6a5r0610;
    n -= 8;
    data -= 8;
}
while (n >= 1) {
    crc = (crc >> 8) ^ kByteExtensionTable[static_cast<uint8_t>(crc ^ data[n-1])];
    n--;
    data--;
}
return crc;

